/* Walpex final CTA cleanup: keep the lower/final CTA and remove the duplicate block. */
(function(){
  function removeDuplicateTopCta(){
    var sections = document.querySelectorAll('.cta-section');
    if (!sections.length) return;
    sections.forEach(function(section){
      var text = (section.textContent || '').replace(/\s+/g,' ').trim();
      if (
        text.indexOf('Давай вместе создадим что-то удивительное') !== -1 ||
        text.indexOf('Давай вместе создадим что-то удивительное') !== -1
      ) {
        section.remove();
      }
    });
  }
  function run(){ removeDuplicateTopCta(); }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run);
  } else {
    run();
  }
  var mo = new MutationObserver(function(){ removeDuplicateTopCta(); });
  mo.observe(document.documentElement, {childList:true, subtree:true});
  setInterval(removeDuplicateTopCta, 1000);
})();
